public class OutboxMessage
{
    public Guid Id { get; set; } = Guid.NewGuid();
    public string Type { get; set; } = string.Empty;
    public string Content { get; set; } = string.Empty;
    public DateTimeOffset OccurredAt { get; set; } = DateTimeOffset.UtcNow;
    public DateTimeOffset? ProcessedAt { get; set; }
    public string? Error { get; set; }
}

public class OutboxInterceptor : SaveChangesInterceptor
{
    private readonly IPublishEndpoint _publisher;
    private readonly ILogger<OutboxInterceptor> _log;

    public OutboxInterceptor(IPublishEndpoint publisher, ILogger<OutboxInterceptor> log)
    {
        _publisher = publisher;
        _log = log;
    }

    public override async ValueTask<InterceptionResult<int>> SavingChangesAsync(DbContextEventData eventData, InterceptionResult<int> result, CancellationToken ct = default)
    {
        var db = eventData.Context!;
        var aggregates = db.ChangeTracker
            .Entries<AggregateRoot<,>>()
            .Where(e => e.Entity.GetUncommittedEvents().Any())
            .ToList();

        if (!aggregates.Any()) return await base.SavingChangesAsync(eventData, result, ct);

        var outboxMessages = aggregates
            .SelectMany(a => a.Entity.GetUncommittedEvents())
            .Select(e => new OutboxMessage
            {
                Type = e.GetType().FullName!,
                Content = JsonSerializer.Serialize(e, e.GetType()),
                OccurredAt = e.OccurredAt
            })
            .ToList();

        db.Set<OutboxMessage>().AddRange(outboxMessages);
        aggregates.ForEach(a => a.Entity.ClearUncommittedEvents());

        return await base.SavingChangesAsync(eventData, result, ct);
    }
}

