public class ReceiptOcrConsumer(
    IReceiptRepository receipts,
    IOcrService ocr,
    ILogger<ReceiptOcrConsumer> log)
    : IConsumer<ReceiptUploaded>
{
    public async Task Consume(ConsumeContext<ReceiptUploaded> ctx)
    {
        var msg = ctx.Message;
        log.LogInformation("Processing receipt {ReceiptId} for report {ReportId}", msg.ReceiptId, msg.ExpenseReportId);

        try
        {
            using var stream = await ocr.DownloadAsync(msg.StorageUrl);
            var result = await ocr.ExtractAsync(stream);

            await receipts.UpdateExtractedFieldsAsync(msg.ReceiptId, new ReceiptExtractionResult
            {
                Vendor = result.Vendor,
                Amount = result.Amount,
                Date = result.Date,
                Confidence = result.Confidence
            }, ctx.CancellationToken);

            // Publish follow-up event for potential re-validation
            await ctx.Publish(new ReceiptOcrCompleted(msg.ReceiptId, result.Confidence), ctx.CancellationToken);
        }
        catch (OcrException ex)
        {
            log.LogWarning(ex, "OCR failed for receipt {ReceiptId} — will retry", msg.ReceiptId);
            throw; // MassTransit retries on transient exceptions
        }
    }
}

public async Task Consume(ConsumeContext<ExpenseReportApproved> ctx)
{
    var msg = ctx.Message;
    var existing = await _eventLogRepo.ExistsAsync(msg.ApprovalEventId, ctx.CancellationToken);
    if (existing)
    {
        log.LogInformation("Duplicate event {EventId} — skipping", msg.ApprovalEventId);
        return; // idempotent skip
    }

    // Process...
    await _notificationService.NotifyApprovalAsync(msg.ReportId, msg.ApproverId, ctx.CancellationToken);
    await _eventLogRepo.RecordAsync(msg.ApprovalEventId, ctx.CancellationToken);
}

builder.Services.AddMassTransit(x =>
{
    x.AddEntityFrameworkOutbox<ExpenseDbContext>(o =>
    {
        o.QueryDelay = TimeSpan.FromSeconds(10);
        o.UsePostgres(); // or UseSqlServer for SQL Server
        o.DisableInboxCleanupService();
    });

    x.AddConsumers([
        typeof(ReceiptOcrConsumer),
        typeof(NotificationConsumer),
        typeof(AccountingExportConsumer)
    ]);

    x.UsingRabbitMq((ctx, cfg) =>
    {
        cfg.Host("localhost", "/", h =>
        {
            h.Username("guest");
            h.Password("guest");
        });

        cfg.ConfigureEndpoints(ctx);

        cfg.ReceiveEndpoint("expense-receipt-ocr", e =>
        {
            e.PrefetchCount = 16;
            e.UseMessageRetry(r => r.Exponential(5, TimeSpan.FromSeconds(1), TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(5)));
            e.UseInMemoryOutbox(); // additional dedup safeguard
            e.ConfigureConsumer<ReceiptOcrConsumer>(ctx);
        });
    });
});
